public void onStrike(ItemStack equipped, EquipmentSlot eqSlot, LivingEntity owner, Map<String, Object> cache,
					 @Nullable DamageSource dSource, ElectricSource eSource)
{
	if(!(dSource instanceof ElectricDamageSource))
		return;
	ElectricDamageSource dmg = (ElectricDamageSource)dSource;
	if(dmg.source.level < 1.75)
	{
		if(cache.containsKey("faraday"))
			cache.put("faraday", (1<<this.type.ordinal())|((Integer)cache.get("faraday")));
		else
			cache.put("faraday", 1<<this.type.ordinal());
		if(cache.containsKey("faraday")&&(Integer)cache.get("faraday")==(1<<4)-1)
			dmg.dmg = 0;
	}
	else
	{
		dmg.dmg *= 1.2;
		if(!(owner instanceof Player)||!((Player)owner).getAbilities().instabuild)
			equipped.hurtAndBreak(2, (dmg.getEntity() instanceof ServerPlayer)?(ServerPlayer)dmg.getEntity(): null, eqSlot);
	}
}

public boolean apply(Entity e)
{
	if(e instanceof LivingEntity living)
		IElectricEquipment.applyToEntity(living, this, source);
	if(dmg > 0)
		e.hurt(this, dmg);
	return dmg > 0;
}

public ElectricDamageSource(Holder<DamageType> tag, IElectricEquipment.ElectricSource source, float amount)
{
	super(tag);
	this.source = source;
	dmg = amount;
}

public static ElectricDamageSource causeTeslaDamage(Level level, float amount, boolean lowPower)
{
	return new ElectricDamageSource(typeHolder(level, Lib.DamageTypes.TESLA), lowPower?TC_LOW: TC_HIGH, amount);
}

static void applyToEntity(LivingEntity entity, @Nullable DamageSource dmg, ElectricSource source)
{
	Map<String, Object> cache = new HashMap<>();
	for(EquipmentSlot slot : EquipmentSlot.values())
	{
		ItemStack s = entity.getItemBySlot(slot);
		if(!s.isEmpty()&&s.getItem() instanceof IElectricEquipment)
			((IElectricEquipment)s.getItem()).onStrike(s, slot, entity, cache, dmg, source);
	}
}

public void onLivingAttacked(LivingDamageEvent.Pre event)
{
	if(event.getEntity() instanceof Player player)
	{
		ItemStack activeStack = player.getUseItem();
		if(!activeStack.isEmpty()&&activeStack.getItem() instanceof IEShieldItem&&event.getOriginalDamage() >= 3&&Utils.canBlockDamageSource(player, event.getSource()))
		{
			float amount = event.getOriginalDamage();
			((IEShieldItem)activeStack.getItem()).hitShield(activeStack, player, event.getSource(), amount, event);
		}

		RandomSource rng = player.getRandom();
		ItemStack powerpack = PowerpackItem.POWERPACK_GETTER.getFrom(player);
		// 33% chance of zapping the attacker, provided they are living and within ~2 blocks
		if(!powerpack.isEmpty()&&PowerpackItem.getUpgradesStatic(powerpack).has(UpgradeEffect.TESLA))
			if(event.getSource().getEntity() instanceof LivingEntity attacker&&attacker.distanceToSqr(player) < 4)
			{
				IEnergyStorage packStorage = powerpack.getCapability(EnergyStorage.ITEM);
				if(packStorage!=null&&packStorage.extractEnergy(PowerpackItem.TESLA_CONSUMPTION, true)==PowerpackItem.TESLA_CONSUMPTION)
				{
					packStorage.extractEnergy(PowerpackItem.TESLA_CONSUMPTION, false);
					ElectricDamageSource dmgsrc = IEDamageSources.causeTeslaDamage(player.level(), 2+player.getRandom().nextInt(4), true);
					if(dmgsrc.apply(attacker))
						attacker.addEffect(new MobEffectInstance(IEPotions.STUNNED, 60));
					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.spark.value(),
							SoundSource.BLOCKS, 2.5F, 0.5F+rng.nextFloat());
				}
			}
	}

	if(event.getSource().is(DamageTypeTags.IS_FIRE)&&event.getEntity().getEffect(IEPotions.FLAMMABLE)!=null)
	{
		int amp = event.getEntity().getEffect(IEPotions.FLAMMABLE).getAmplifier();
		float mod = 1.5f+((amp*amp)*.5f);
		event.setNewDamage(event.getNewDamage()*mod);
	}
	if(("flux".equals(event.getSource().getMsgId())||event.getSource().is(DamageTypes.RAZOR_SHOCK)||
			event.getSource() instanceof ElectricDamageSource)&&event.getEntity().getEffect(IEPotions.CONDUCTIVE)!=null)
	{
		int amp = event.getEntity().getEffect(IEPotions.CONDUCTIVE).getAmplifier();
		float mod = 1.5f+((amp*amp)*.5f);
		event.setNewDamage(event.getNewDamage()*mod);
	}

	boolean isBoss = event.getEntity().getType().is(EntityTypes.BOSSES);
	if(isBoss&&event.getNewDamage() >= event.getEntity().getHealth()&&event.getSource().getEntity() instanceof Player&&((Player)event.getSource().getEntity()).getItemInHand(InteractionHand.MAIN_HAND).getItem() instanceof DrillItem)
		Utils.unlockIEAdvancement((Player)event.getSource().getEntity(), "tools/secret_drillbreak");
}

public void hitShield(ItemStack stack, Player player, DamageSource source, float amount, LivingDamageEvent.Pre event)
{
	var upgrades = getUpgrades(stack);
	if(upgrades.has(UpgradeEffect.FLASH)&&!upgrades.get(UpgradeEffect.FLASH).isOnCooldown())
	{
		Vec3 look = player.getLookAngle();
		//Offsets Player position by look backwards, then truncates cone at 1
		List<LivingEntity> targets = Utils.getTargetsInCone(player.getCommandSenderWorld(), player.position().subtract(look), player.getLookAngle().scale(9), 1.57079f, .5f);
		for(LivingEntity t : targets)
			if(!player.equals(t))
			{
				t.addEffect(new MobEffectInstance(IEPotions.FLASHED, 100, 1));
				if(t instanceof Mob)
					((Mob)t).setTarget(null);
			}
		upgrades = upgrades.with(UpgradeEffect.FLASH, new Cooldown(40));
	}
	if(upgrades.has(UpgradeEffect.SHOCK)&&!upgrades.get(UpgradeEffect.SHOCK).isOnCooldown())
	{
		boolean b = false;
		if(event.getSource().is(DamageTypeTags.IS_PROJECTILE)&&event.getSource().getDirectEntity()!=null)
		{
			Entity projectile = event.getSource().getDirectEntity();
			projectile.discard();
			event.setNewDamage(0);
			b = true;
		}
		if(event.getSource().getEntity()!=null&&event.getSource().getEntity() instanceof LivingEntity&&event.getSource().getEntity().distanceToSqr(player) < 4)
		{
			ElectricDamageSource dmgsrc = IEDamageSources.causeTeslaDamage(event.getEntity().level(), 1, true);
			dmgsrc.apply(event.getSource().getEntity());
			b = true;
		}
		if(b)
		{
			upgrades = upgrades.with(UpgradeEffect.SHOCK, new Cooldown(40));
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.spark.value(),
					SoundSource.BLOCKS, 2.5F, 0.5F+ApiUtils.RANDOM.nextFloat());
		}
	}
	stack.set(IEDataComponents.UPGRADE_DATA, upgrades);
}

