public void onEntityDamaged(LivingHurtEvent event) {
    if (event.getSource().damageType.equals(RegistryManager.damage_ember.damageType)) {
        if (event.getEntityLiving().isPotionActive(Potion.getPotionFromResourceLocation("fire_resistance"))) {
            event.setAmount(event.getAmount() * 0.5f);
        }
    }
    final Entity trueSource = event.getSource().getTrueSource();
    if (!(trueSource instanceof EntityPlayer))
        return;
    final EntityPlayer player = (EntityPlayer) trueSource;
    final ItemStack heldStack = player.getHeldItemMainhand();
    if (heldStack.isEmpty())
        return;
    if (heldStack.getItem() == RegistryManager.tyrfing) {
        event.getEntity().playSound(SoundManager.TYRFING_HIT,1.0f,1.0f);
        if (!event.getEntity().world.isRemote)
            PacketHandler.INSTANCE.sendToAll(new MessageTyrfingBurstFX(event.getEntity().posX, event.getEntity().posY + event.getEntity().height / 2.0f, event.getEntity().posZ));
        event.setAmount((event.getAmount() / 4.0f) * (4.0f + (float) event.getEntityLiving().getEntityAttribute(SharedMonsterAttributes.ARMOR).getAttributeValue() * 1.0f));
    }
    if (heldStack.getItem() instanceof IEmberChargedTool) {
        if (!player.capabilities.isCreativeMode && !((IEmberChargedTool) heldStack.getItem()).hasEmber(heldStack))
            event.setCanceled(true);
        if (!event.isCanceled() && event.getAmount() > 0) {
            event.getEntityLiving().setFire(1);
            if (!event.getEntityLiving().getEntityWorld().isRemote) {
                PacketHandler.INSTANCE.sendToAll(new MessageEmberBurstFX(event.getEntityLiving().posX, event.getEntityLiving().posY + event.getEntityLiving().getEyeHeight() / 1.5, event.getEntityLiving().posZ));
                heldStack.getTagCompound().setBoolean("didUse", true);
            }
        }
    }
}

public boolean hasEmber(ItemStack stack) {
	if (stack.hasTagCompound()){
		return stack.getTagCompound().getBoolean("poweredOn");
	}
	return false;
}

public void onUpdate(ItemStack stack, World world, Entity entity, int slot, boolean selected){
	if (!stack.hasTagCompound()){
		stack.setTagCompound(new NBTTagCompound());
		stack.getTagCompound().setInteger("tickCount", 0);
		stack.getTagCompound().setInteger("cooldown", 0);
		stack.getTagCompound().setBoolean("poweredOn", false);
		stack.getTagCompound().setBoolean("didUse", false);
	}
	else {
		if (stack.getTagCompound().getInteger("cooldown") > 0){
			stack.getTagCompound().setInteger("cooldown", stack.getTagCompound().getInteger("cooldown")-1);
		}
		if (entity instanceof EntityPlayer){
			stack.getTagCompound().setInteger("tickCount", stack.getTagCompound().getInteger("tickCount")+1);
			if (stack.getTagCompound().getInteger("tickCount") >= 5){
				stack.getTagCompound().setInteger("tickCount", 0);
				if (EmberInventoryUtil.getEmberTotal(((EntityPlayer)entity)) > 5.0){
					if (!stack.getTagCompound().getBoolean("poweredOn")){
						stack.getTagCompound().setBoolean("poweredOn", true);
					}
				}
				else {
					if (stack.getTagCompound().getBoolean("poweredOn")){
						stack.getTagCompound().setBoolean("poweredOn", false);
					}
				}
			}
			if (stack.getTagCompound().getBoolean("didUse")){
				stack.getTagCompound().setBoolean("didUse", false);
				EmberInventoryUtil.removeEmber(((EntityPlayer)entity), 5.0);
				if (EmberInventoryUtil.getEmberTotal((EntityPlayer)entity) < 5.0){
					stack.getTagCompound().setBoolean("poweredOn", false);
				}
			}
		}
	}
}

public static double getEmberTotal(EntityPlayer player) {
    double amount = 0;
    for (int i = 0; i < 36; i++) {
        ItemStack stack = player.inventory.getStackInSlot(i);
        if (stack.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
            IEmberCapability capability = stack.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
            if (capability instanceof IInventoryEmberCell)
                amount += capability.getEmber();
        }
    }
    ItemStack offhandItem = player.getHeldItem(EnumHand.OFF_HAND);
    if (offhandItem.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
        IEmberCapability capability = offhandItem.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
        if (capability instanceof IHeldEmberCell)
            amount += capability.getEmber();
    }
    ItemStack heldItem = player.getHeldItem(EnumHand.MAIN_HAND);
    if (heldItem.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
        IEmberCapability capability = heldItem.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
        if (capability instanceof IHeldEmberCell)
            amount += capability.getEmber();
    }
    if (ConfigManager.isBaublesIntegrationEnabled()) {
        amount += BaublesIntegration.getEmberTotal(player);
    }
    return amount;
}

public static void removeEmber(EntityPlayer player, double amount) {
    EmberRemoveEvent event = new EmberRemoveEvent(player, amount);
    MinecraftForge.EVENT_BUS.post(event);
    double temp = event.getFinal();

    ItemStack offhandItem = player.getHeldItem(EnumHand.OFF_HAND);
    if (offhandItem.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
        IEmberCapability capability = offhandItem.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
        if (capability instanceof IHeldEmberCell)
            temp -= capability.removeAmount(temp, true);
    }
    ItemStack heldItem = player.getHeldItem(EnumHand.MAIN_HAND);
    if (heldItem.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
        IEmberCapability capability = heldItem.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
        if (capability instanceof IHeldEmberCell)
            temp -= capability.removeAmount(temp, true);
    }
    if (ConfigManager.isBaublesIntegrationEnabled()) {
        temp = BaublesIntegration.removeEmber(player, temp);
    }
    for (int i = 0; i < 36; i++) {
        ItemStack stack = player.inventory.getStackInSlot(i);
        if (stack.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)) {
            IEmberCapability capability = stack.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null);
            if (capability instanceof IInventoryEmberCell)
                temp -= capability.removeAmount(temp, true);
        }
    }
}

