package net.machinemuse.utils;

import net.machinemuse.api.ModuleManager;
import net.machinemuse.powersuits.common.Config;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.util.DamageSource;

import java.util.List;

public class MuseHeatUtils {

    public static final String MAXIMUM_HEAT = "Maximum Heat";
    public static final String CURRENT_HEAT = "Current Heat";

    public static double getPlayerHeat(EntityPlayer player) {
        double avail = 0;
        for (ItemStack stack : MuseItemUtils.getModularItemsInInventory(player)) {
            avail += getItemHeat(stack);
        }
        return avail;
    }

    public static double getMaxHeat(EntityPlayer player) {
        double avail = 0;
        for (ItemStack stack : MuseItemUtils.getModularItemsInInventory(player)) {
            avail += getMaxHeat(stack);
        }
        return avail + Config.baseMaxHeat();
    }

    public static double getMaxHeat(ItemStack stack) {
        return ModuleManager.computeModularProperty(stack, MAXIMUM_HEAT);
    }

    public static void coolPlayer(EntityPlayer player, double coolDegrees) {
        coolDegrees = coolDegrees * 0.25;
        List<ItemStack> items = MuseItemUtils.getModularItemsInInventory(player);
        if (player.isHandActive()) {
            items.remove(player.inventory.getCurrentItem());
        }
        for (ItemStack stack : items) {
            double currHeat = getItemHeat(stack);
            if (coolDegrees > 0) {
                if (currHeat > coolDegrees) {
                    setItemHeat(stack, currHeat - coolDegrees);
                    return;
                } else {
                    coolDegrees -= currHeat;
                    setItemHeat(stack, 0);
                }
            } else {
                return;
            }
        }
    }

    public static void heatPlayer(EntityPlayer player, double heatDegrees) {
        List<ItemStack> items = MuseItemUtils.getModularItemsInInventory(player);
        if (player.isHandActive()) {
            items.remove(player.inventory.getCurrentItem());
        }
        for (ItemStack stack : items) {
            double currHeat = getItemHeat(stack);
            double maxHeat = getMaxHeat(stack);
            if (currHeat + heatDegrees < maxHeat) {
                setItemHeat(stack, currHeat + heatDegrees);
                return;
            } else {
                heatDegrees -= (maxHeat - currHeat);
                setItemHeat(stack, maxHeat);
            }
        }
        double heatPerStack = heatDegrees / items.size();
        for (ItemStack stack : items) {
            heatItem(stack, heatPerStack);
        }
    }

    public static double getItemHeat(ItemStack stack) {
        return MuseItemUtils.getDoubleOrZero(stack, CURRENT_HEAT);
    }

    public static void setItemHeat(ItemStack stack, double heat) {
        MuseItemUtils.setDoubleOrRemove(stack, CURRENT_HEAT, heat);
    }

    public static void heatItem(ItemStack stack, double value) {
        setItemHeat(stack, getItemHeat(stack) + value);
    }

    public static void coolItem(ItemStack stack, double value) {
        setItemHeat(stack, getItemHeat(stack) - value);
    }

    public static final DamageSource overheatDamage = new OverheatDamage();

    protected static final class OverheatDamage extends DamageSource {
        public OverheatDamage() {
            super("Overheat");
            this.setFireDamage();
            this.setDamageBypassesArmor();
        }

        public boolean equals(DamageSource other) {
            return other.damageType.equals(this.damageType);
        }
    }
}

public void onPlayerUpdate(LivingEvent.LivingUpdateEvent e) {
    if (e.getEntity() instanceof EntityPlayer) {
        EntityPlayer player = (EntityPlayer) e.getEntity();

        List<ItemStack> modularItemsEquipped = MuseItemUtils.modularItemsEquipped(player);
        double totalWeight = MuseItemUtils.getPlayerWeight(player);
        double weightCapacity = Config.getWeightCapacity();

        for (ItemStack stack : modularItemsEquipped) {
            // Temporary Advanced Rocketry hack Not the best way but meh.
            NBTTagList tagList = stack.getEnchantmentTagList();
            if (tagList != null && !tagList.hasNoTags()) {
                if (tagList.tagCount() == 1) {
                    if (!(tagList.getCompoundTagAt(0).getShort("id") == 128))
                        stack.getTagCompound().removeTag("ench");
                } else {
                    NBTTagCompound ar = null;
                    for (int i = 0; i < tagList.tagCount(); i++) {
                        NBTTagCompound nbtTag = tagList.getCompoundTagAt(i);
                        if ((nbtTag.getShort("id") == 128)) {
                            ar = nbtTag;
                        }
                    }
                    stack.getTagCompound().removeTag("ench");
                    if (ar != null) {
                        stack.getTagCompound().setTag("ench", ar);
                    }
                }
            }
        }

        boolean foundItemWithModule;
        for (IPlayerTickModule module : ModuleManager.getPlayerTickModules()) {
            foundItemWithModule = false;
            for (ItemStack itemStack : modularItemsEquipped) {
                if (module.isValidForItem(itemStack)) {
                    if (ModuleManager.itemHasActiveModule(itemStack, module.getDataName())) {
                        module.onPlayerTickActive(player, itemStack);
                        foundItemWithModule = true;
                    }
                }
            }
            if (!foundItemWithModule) {
                for (ItemStack itemStack : modularItemsEquipped) {
                    module.onPlayerTickInactive(player, itemStack);
                }
            }
        }

        boolean foundItem = modularItemsEquipped.size() > 0;

        if (foundItem) {
            player.fallDistance = (float) MovementManager.computeFallHeightFromVelocity(MuseMathUtils.clampDouble(player.motionY, -1000.0, 0.0));
            if (totalWeight > weightCapacity) {
                player.motionX *= weightCapacity / totalWeight;
                player.motionZ *= weightCapacity / totalWeight;
            }

            // Heat update
            MuseHeatUtils.coolPlayer(player, MusePlayerUtils.getPlayerCoolingBasedOnMaterial(player));
            double maxHeat = MuseHeatUtils.getMaxHeat(player);
            double currHeat = MuseHeatUtils.getPlayerHeat(player);
            if (currHeat > maxHeat) {
                player.attackEntityFrom(MuseHeatUtils.overheatDamage, (float) (Math.sqrt(currHeat - maxHeat)/* was (int) */ / 4));
                player.setFire(1);
            } else {
                player.extinguish();
            }

            // Sound update
            double velsq2 = MuseMathUtils.sumsq(player.motionX, player.motionY, player.motionZ) - 0.5;
            if (player.worldObj.isRemote && NuminaConfig.useSounds()) {
                if (player.isAirBorne && velsq2 > 0) {
                    Musique.playerSound(player, SoundDictionary.SOUND_EVENT_GLIDER, SoundCategory.PLAYERS, (float) (velsq2 / 3), 1.0f, true);
                } else {
                    Musique.stopPlayerSound(player, SoundDictionary.SOUND_EVENT_GLIDER);
                }
            }
        } else if (player.worldObj.isRemote && NuminaConfig.useSounds())
            Musique.stopPlayerSound(player, SoundDictionary.SOUND_EVENT_GLIDER);
    }
}

public static List<ItemStack> getModularItemsInInventory(IInventory inv) {
    ArrayList<ItemStack> stacks = new ArrayList<>();

    for (int i = 0; i < inv.getSizeInventory(); i++) {
        ItemStack stack = inv.getStackInSlot(i);
        if (stack != null && stack.getItem() instanceof IModularItem) {
            stacks.add(stack);
        }
    }
    return stacks;
}

public static List<ItemStack> getModularItemsInInventory(EntityPlayer player) {
    return getModularItemsInInventory(player.inventory);
}

